package com.codeguardian.service.cache; import com.codeguardian.entity.Finding; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.concurrent.*; @Service public class SemanticReviewCache{private record Entry(List<Finding> findings,Instant until){}private final Map<String,Entry> store=new ConcurrentHashMap<>();private final SemanticFingerprintService fps;public SemanticReviewCache(SemanticFingerprintService f){fps=f;}public Optional<List<Finding>> get(String code){return lookup(fps.exact(code)).or(()->lookup(fps.similar(code)));}public void put(String code,List<Finding> findings,Duration ttl){Instant until=Instant.now().plus(ttl);store.put(fps.exact(code),new Entry(List.copyOf(findings),until));store.put(fps.similar(code),new Entry(List.copyOf(findings),until));}private Optional<List<Finding>> lookup(String k){Entry e=store.get(k);if(e==null)return Optional.empty();if(e.until().isBefore(Instant.now())){store.remove(k);return Optional.empty();}return Optional.of(e.findings());}}
